<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;use Suave\Numeros as N;
$report=$db->one('SELECT r.*,a.nombre,a.bytes FROM reportes r JOIN archivos a ON a.id=r.archivo_id WHERE r.id=?',[(int)($_GET['id']??0)]);if(!$report)throw new Suave\ErrorUsuario('La versión de reporte no existe.');
$reportPeriod=(new Suave\Periodos($db))->get($report['mes']);$count=(int)$db->value('SELECT COUNT(*) FROM reporte_filas WHERE reporte_id=?',[$report['id']]);$pages=max(1,(int)ceil($count/100));$number=max(1,min($pages,(int)($_GET['pagina']??1)));$rows=$db->all('SELECT * FROM reporte_filas WHERE reporte_id=? ORDER BY id LIMIT 100 OFFSET '.(($number-1)*100),[$report['id']]);
?>
<div class="page-heading"><div><h1>Reporte v<?=$report['numero']?></h1><p><?=V::h(ucfirst(V::monthLabel($report['mes'])))?> · <?=$report['modalidad']==='detalle'?'Detalle de entregas':'Totales por sucursal'?></p></div><?=V::badge((int)$reportPeriod['reporte_id']===(int)$report['id']?'En uso':'Anterior')?></div>
<div class="action-row spread"><?=$w->link('← Volver a versiones','reportes',['historial'=>1,'mes'=>$report['mes']])?><?php if((int)$reportPeriod['reporte_id']!==(int)$report['id']):?><form method="post" data-confirm="¿Usar esta versión como fuente de todo el mes? La comparación se revisará de nuevo; las fuentes anteriores se conservarán."><?=V::protect('reporte_usar')?><?=V::hidden('id',$report['id'])?><button class="button primary" type="submit" <?=$reportPeriod['estado']==='Revisado'?'disabled':''?>>Usar esta versión</button></form><?php endif?></div>
<div class="soft-panel"><h2>Archivo original</h2><?=$w->link($report['nombre'],'archivo',['id'=>$report['archivo_id']],'text-link')?><p class="hint"><?=$count?> filas conservadas · Importado el <?=V::h($report['creado_en'])?>. Consultar esta versión no cambia la fuente en uso.</p></div>
<?php $reading=Suave\Datos::decode($report['lectura_json']);if(!empty($reading['excluidas'])):?><p class="notice warning"><?=count($reading['excluidas'])?> filas de otros meses se excluyeron de esta versión. Consulta el archivo original para ver el conjunto completo.</p><?php endif?>
<div class="table-wrap"><table><thead><tr><th>Hoja</th><th>Fila</th><th>Sucursal</th><th>Fecha</th><th>Folio</th><th>Importe</th><th>Datos recibidos</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="report-source-row"><td><?=V::h($r['hoja'])?></td><td><?=$r['fila']?></td><td><?=V::h($r['sucursal_codigo'].' · '.$r['sucursal_nombre'])?></td><td><?=$r['fecha']?V::date($r['fecha']):'No disponible'?></td><td><?=V::h($r['folio']?:'Sin folio')?></td><td><?=N::currency((int)$r['importe_centavos'])?></td><td><?php include __DIR__.'/_reporte_origen.php';?></td></tr><?php endforeach?></tbody></table></div>
<div class="pagination"><span>Página <?=$number?> de <?=$pages?></span><div class="action-row"><?php if($number>1):?><?=$w->link('Anterior','reporte_version',['id'=>$report['id'],'mes'=>$report['mes'],'pagina'=>$number-1])?><?php endif?><?php if($number<$pages):?><?=$w->link('Siguiente','reporte_version',['id'=>$report['id'],'mes'=>$report['mes'],'pagina'=>$number+1])?><?php endif?></div></div>
